1: /* ROMFOLIO — biblioteca local e exportador de projeto Android. */
2: (() => {
3:   'use strict';
4: 
5:   // 1. Configuração e estado da sessão
6:   const ALLOWED_EXTENSIONS = new Set([
7:     'nes', 'gb', 'gbc', 'gba', 'sfc', 'smc', 'nds', 'n64', 'z64',
8:     'iso', 'bin', 'rom', 'zip',
9:   ]);
10:   const MAX_EXPORT_BYTES = 512 * 1024 * 1024;
11:   const SYSTEMS = {
12:     gba: { label: 'GBA', icon: '🟩', color: '' },
13:     nes: { label: 'NES', icon: '🟥', color: 'orange' },
14:     snes: { label: 'SNES', icon: '🟦', color: 'purple' },
15:     gb: { label: 'GB', icon: '⬛', color: '' },
16:     other: { label: 'Outro', icon: '🎮', color: 'orange' },
17:   };
18:   const state = {
19:     games: [
20:       { name: 'Pocket Garden', file: 'pocket-garden.gba', system: 'gba', size: 512 * 1024, example: true, addedAt: 3 },
21:       { name: 'Tiny Adventure', file: 'tiny-adventure.nes', system: 'nes', size: 256 * 1024, example: true, addedAt: 2 },
22:       { name: 'Moonlight Quest', file: 'moonlight-quest.sfc', system: 'snes', size: 1024 * 1024, example: true, addedAt: 1 },
23:     ],
24:     selectedSystem: 'gba',
25:     newestFirst: true,
26:     exporting: false,
27:     toastTimer: null,
28:   };
29: 
30:   // 2. Elementos e utilitários de interface
31:   const $ = (selector) => document.querySelector(selector);
32:   const els = {
33:     search: $('#search'), systemFilter: $('#systemFilter'), table: $('#tableWrap'),
34:     input: $('#fileInput'), drop: $('#drop'), modal: $('#modalBack'),
35:     exportButton: $('#exportBtn'), cancelButton: $('#cancel'), progress: $('#progress'),
36:     progressBar: $('#progressBar'), progressLabel: $('#progressLabel'),
37:     packageId: $('#packageId'), appName: $('#appName'), target: $('#target'),
38:     activity: $('#activity'), sortButton: $('#sortBtn'),
39:   };
40:   const encoder = new TextEncoder();
41:   const formatBytes = (bytes) => bytes < 1024 * 1024
42:     ? `${Math.max(1, Math.round(bytes / 1024))} KB`
43:     : `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
44:   const escapeHtml = (value) => String(value).replace(/[&<>"']/g, (char) => ({
45:     '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;',
46:   })[char]);
47:   const safeFileName = (name) => name
48:     .replace(/[\\/\u0000-\u001f\u007f]/g, '_').replace(/^\.+/, '_').trim() || 'jogo.rom';
49: 
50:   function showToast(message) {
51:     const toast = $('#toast');
52:     toast.textContent = message;
53:     toast.classList.add('show');
54:     clearTimeout(state.toastTimer);
55:     state.toastTimer = setTimeout(() => toast.classList.remove('show'), 2600);
56:   }
57: 
58:   function logActivity(title, detail, icon = '＋') {
59:     const item = document.createElement('div');
60:     item.className = 'activity';
61:     const iconElement = document.createElement('div');
62:     iconElement.className = 'act-icon';
63:     iconElement.textContent = icon;
64:     const description = document.createElement('p');
65:     description.append(document.createTextNode(title));
66:     const metadata = document.createElement('small');
67:     metadata.textContent = detail;
68:     description.append(metadata);
69:     item.append(iconElement, description);
70:     els.activity.prepend(item);
71:   }
72: 
73:   function render() {
74:     const query = els.search.value.trim().toLocaleLowerCase();
75:     const system = els.systemFilter.value;
76:     const visibleGames = state.games
77:       .filter((game) => system === 'all' || game.system === system)
78:       .filter((game) => `${game.name} ${game.file} ${game.system}`.toLocaleLowerCase().includes(query))
79:       .sort((a, b) => (a.addedAt - b.addedAt) * (state.newestFirst ? -1 : 1));
80: 
81:     $('#statGames').textContent = String(state.games.length).padStart(2, '0');
82:     $('#statSize').textContent = formatBytes(state.games.reduce((total, game) => total + game.size, 0));
83:     $('#statSystems').textContent = String(new Set(state.games.map((game) => game.system)).size).padStart(2, '0');
84:     els.sortButton.textContent = state.newestFirst ? 'Mais recentes ↓' : 'Mais antigos ↑';
85: 
86:     if (!visibleGames.length) {
87:       els.table.innerHTML = '<div class="empty"><div class="big">⌕</div>Nenhum jogo encontrado.</div>';
88:       return;
89:     }
90: 
91:     els.table.innerHTML = `<table class="table"><thead><tr><th>JOGO</th><th>SISTEMA</th><th>TAMANHO</th><th>STATUS</th><th></th></tr></thead><tbody>${visibleGames.map((game) => {
92:       const systemInfo = SYSTEMS[game.system] || SYSTEMS.other;
93:       const status = game.example ? 'Exemplo' : 'Nesta sessão';
94:       return `<tr><td><div class="game"><div class="cover ${systemInfo.color}">${systemInfo.icon}</div><div><b>${escapeHtml(game.name)}</b><small>${escapeHtml(game.file)}</small></div></div></td><td><span class="tag">${systemInfo.label}</span></td><td>${formatBytes(game.size)}</td><td><span style="color:#a9d86b">●　${status}</span></td><td><button class="dots" data-remove="${state.games.indexOf(game)}" title="Remover" aria-label="Remover ${escapeHtml(game.name)}">···</button></td></tr>`;
95:     }).join('')}</tbody></table>`;
96:     els.table.querySelectorAll('[data-remove]').forEach((button) => {
97:       button.addEventListener('click', () => {
98:         state.games.splice(Number(button.dataset.remove), 1);
99:         render();
100:         showToast('Arquivo removido da lista.');
101:       });
102:     });
103:   }
104: 
105:   // 3. Importação e identificação de arquivos
106:   function identifySystem(fileName) {
107:     const extension = fileName.split('.').pop().toLowerCase();
108:     if (extension === 'gba') return 'gba';
109:     if (extension === 'nes') return 'nes';
110:     if (['sfc', 'smc'].includes(extension)) return 'snes';
111:     if (['gb', 'gbc'].includes(extension)) return 'gb';
112:     return 'other';
113:   }
114: 
115:   function uniqueFileName(fileName) {
116:     const safeName = safeFileName(fileName);
117:     const dot = safeName.lastIndexOf('.');
118:     const base = dot > 0 ? safeName.slice(0, dot) : safeName;
119:     const extension = dot > 0 ? safeName.slice(dot) : '';
120:     let candidate = safeName;
121:     let suffix = 2;
122:     const existing = new Set(state.games.filter((game) => !game.example).map((game) => game.file.toLowerCase()));
123:     while (existing.has(candidate.toLowerCase())) candidate = `${base} (${suffix++})${extension}`;
124:     return candidate;
125:   }
126: 
127:   async function addFiles(fileList) {
128:     const files = Array.from(fileList);
129:     const added = [];
130:     const rejected = [];
131:     for (const file of files) {
132:       const extension = file.name.split('.').pop().toLowerCase();
133:       if (!file.size || !ALLOWED_EXTENSIONS.has(extension)) {
134:         rejected.push(file.name);
135:         continue;
136:       }
137:       const fileName = uniqueFileName(file.name);
138:       added.push({
139:         name: fileName.replace(/\.[^.]+$/, '').replace(/[-_]/g, ' '),
140:         file: fileName,
141:         size: file.size,
142:         system: identifySystem(fileName),
143:         blob: file,
144:         example: false,
145:         addedAt: Date.now() + added.length,
146:       });
147:     }
148:     state.games.unshift(...added.reverse());
149:     render();
150:     if (added.length) {
151:       showToast(`${added.length} arquivo(s) adicionado(s) à sessão.`);
152:       logActivity('Arquivos adicionados', `${added.length} arquivo(s) · sessão atual`);
153:     } else if (rejected.length) {
154:       showToast(`Formato não reconhecido ou arquivo vazio: ${rejected[0]}`);
155:     }
156:   }
157: 
158:   function setSelectedSystem(system) {
159:     state.selectedSystem = system;
160:     document.querySelectorAll('.platform').forEach((button) => {
161:       const selected = button.dataset.system.toLowerCase() === system;
162:       button.classList.toggle('selected', selected);
163:       button.setAttribute('aria-pressed', String(selected));
164:     });
165:     const targetIndex = { gba: 0, nes: 1, snes: 2, other: 3 }[system] ?? 3;
166:     els.target.selectedIndex = targetIndex;
167:   }
168: 
169:   // 4. Eventos da interface
170:   els.search.addEventListener('input', render);
171:   els.systemFilter.addEventListener('change', render);
172:   $('#addBtn').addEventListener('click', () => els.input.click());
173:   $('#browseBtn').addEventListener('click', () => els.input.click());
174:   els.input.addEventListener('change', (event) => {
175:     addFiles(event.target.files);
176:     event.target.value = '';
177:   });
178:   els.drop.addEventListener('dragover', (event) => {
179:     event.preventDefault();
180:     els.drop.classList.add('over');
181:   });
182:   els.drop.addEventListener('dragleave', () => els.drop.classList.remove('over'));
183:   els.drop.addEventListener('drop', (event) => {
184:     event.preventDefault();
185:     els.drop.classList.remove('over');
186:     addFiles(event.dataTransfer.files);
187:   });
188:   document.querySelectorAll('.platform').forEach((button) => {
189:     button.addEventListener('click', () => setSelectedSystem(button.dataset.system.toLowerCase()));
190:   });
191:   els.target.addEventListener('change', () => {
192:     const systems = ['gba', 'nes', 'snes', 'other'];
193:     setSelectedSystem(systems[els.target.selectedIndex] || 'other');
194:   });
