283:   function buildProjectFiles(name, applicationId, games) {
284:     const packagePath = applicationId.replace(/\./g, '/');
285:     const files = [
286:       { name: 'README.md', data: textFile(`# ${name}\n\nProjeto Android Studio gerado pelo ROMFOLIO.\n\n## Importante\nEste projeto contém os arquivos selecionados e um catálogo Android simples. **Ele não inclui um emulador**, portanto não executa os jogos. Integre um emulador compatível e licenciado para a plataforma antes de distribuir ou instalar como jogo. Use somente conteúdo próprio, homebrew ou autorizado. Verifique a legislação aplicável e as licenças de qualquer runtime.\n\n## Compilar\nAbra esta pasta no Android Studio, sincronize o Gradle e use Build > Build APK(s). Requer Android Studio com Android SDK instalado e conexão para baixar o plugin Gradle.\n\nOs arquivos ROM são copiados para app/src/main/assets/games/. O identificador configurado é ${applicationId}.\n`) },
287:       { name: 'settings.gradle.kts', data: textFile('pluginManagement { repositories { google(); mavenCentral(); gradlePluginPortal() } }\ndependencyResolutionManagement { repositoriesMode.set(RepositoriesMode.FAIL_ON_PROJECT_REPOS); repositories { google(); mavenCentral() } }\nrootProject.name = "ROMFolio"\ninclude(":app")\n') },
288:       { name: 'build.gradle.kts', data: textFile('plugins { id("com.android.application") version "8.7.3" apply false; id("org.jetbrains.kotlin.android") version "2.0.21" apply false }\n') },
289:       { name: 'app/build.gradle.kts', data: textFile(`plugins { id("com.android.application"); id("org.jetbrains.kotlin.android") }\n\nandroid { namespace = "${applicationId}"; compileSdk = 35\n defaultConfig { applicationId = "${applicationId}"; minSdk = 23; targetSdk = 35; versionCode = 1; versionName = "1.0" }\n}\n`) },
290:       { name: 'app/src/main/AndroidManifest.xml', data: textFile(`<?xml version="1.0" encoding="utf-8"?>\n<manifest xmlns:android="http://schemas.android.com/apk/res/android"><application android:theme="@android:style/Theme.Material.NoActionBar" android:label="${xmlEscape(name)}" android:usesCleartextTraffic="false"><activity android:name=".MainActivity" android:exported="true"><intent-filter><action android:name="android.intent.action.MAIN"/><category android:name="android.intent.category.LAUNCHER"/></intent-filter></activity></application></manifest>\n`) },
291:       { name: `app/src/main/java/${packagePath}/MainActivity.kt`, data: textFile(`package ${applicationId}\n\nimport android.app.Activity\nimport android.os.Bundle\nimport android.graphics.Color\nimport android.view.Gravity\nimport android.widget.LinearLayout\nimport android.widget.TextView\n\nclass MainActivity : Activity() {\n override fun onCreate(savedInstanceState: Bundle?) { super.onCreate(savedInstanceState)\n  val root = LinearLayout(this).apply { orientation = LinearLayout.VERTICAL; setPadding(32,48,32,32); setBackgroundColor(Color.rgb(16,18,15)) }\n  root.addView(TextView(this).apply { text = ${kotlinString(name)}; textSize = 25f; setTextColor(Color.rgb(200,241,105)) })\n  root.addView(TextView(this).apply { text = "Sua coleção"; textSize=16f; setTextColor(Color.WHITE); setPadding(0,24,0,12) })\n  val games = assets.list("games")?.filter { it.isNotBlank() } ?: emptyList()\n  if (games.isEmpty()) root.addView(TextView(this).apply { text="Nenhum arquivo encontrado."; setTextColor(Color.LTGRAY) })\n  games.forEach { game -> root.addView(TextView(this).apply { text="🎮  $game"; textSize=15f; setTextColor(Color.WHITE); setPadding(0,14,0,14) }) }\n  root.addView(TextView(this).apply { text="Para jogar, integre um emulador compatível e licenciado."; textSize=12f; setTextColor(Color.LTGRAY); gravity=Gravity.CENTER_VERTICAL; setPadding(0,20,0,0) })\n  setContentView(root)\n }\n}\n`) },
292:       { name: 'romfolio.json', data: textFile(JSON.stringify({
293:         name,
294:         applicationId,
295:         platform: els.target.value,
296:         createdAt: new Date().toISOString(),
297:         games: games.map((game) => ({ name: game.name, file: game.file, system: game.system, size: game.size })),
298:       }, null, 2)) },
299:     ];
300:     for (const game of games) {
301:       files.push({ name: `app/src/main/assets/games/${safeFileName(game.file)}`, data: game.blob });
302:     }
303:     return files;
304:   }
305: 
306:   els.exportButton.addEventListener('click', async () => {
307:     const games = state.games.filter((game) => !game.example && game.blob);
308:     if (!games.length) {
309:       showToast('Adicione arquivos próprios antes de exportar; exemplos não são incluídos.');
310:       return;
311:     }
312:     const name = els.appName.value.trim() || 'Minha coleção';
313:     const applicationId = els.packageId.value.trim() || 'com.exemplo.minhacolecao';
314:     if (!/^[a-zA-Z][a-zA-Z0-9_]*(\.[a-zA-Z][a-zA-Z0-9_]*)+$/.test(applicationId)) {
315:       showToast('Use um identificador como com.exemplo.meuapp.');
