322:       return;
323:     }
324: 
325:     state.exporting = true;
326:     els.exportButton.disabled = true;
327:     els.cancelButton.disabled = true;
328:     els.progress.classList.add('show');
329:     let progress = 0;
330:     const ticker = setInterval(() => {
331:       progress = Math.min(progress + 12, 82);
332:       els.progressBar.style.width = `${progress}%`;
333:       els.progressLabel.textContent = progress < 40 ? 'Organizando arquivos…' : progress < 75 ? 'Montando projeto Android…' : 'Preparando download…';
334:     }, 100);
